BEGIN TRAN;

-- 1) unique key incl. PART B
IF EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'UX_MST_PART_CODE_PARTA' AND object_id = OBJECT_ID('Nexus.Parts'))
    DROP INDEX UX_MST_PART_CODE_PARTA ON Nexus.Parts;
CREATE UNIQUE INDEX UX_MST_PART_CODE_PARTA ON Nexus.Parts (PartCode, PartA, PartB);

-- 2) existing STORE-SUB items matched by PART B: correct data from ERP
UPDATE p SET p.Category = N'B',
             p.Model = e.Model,
             p.PartNumber = e.PartNo,
             p.Description = e.Name,
             p.PackSize = ISNULL(e.Pack, p.PackSize)
FROM Nexus.Parts p
JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @stk
JOIN #e e ON e.Code = LTRIM(RTRIM(p.PartB));
DECLARE @upd INT = @@ROWCOUNT;

-- 3) every STORE-SUB item: Product Code same as PART B (or empty) -> '-' · QR cleared
UPDATE p SET p.PartCode = CASE WHEN NULLIF(LTRIM(RTRIM(p.PartCode)), '') IS NULL OR LTRIM(RTRIM(p.PartCode)) = LTRIM(RTRIM(p.PartB)) THEN '-' ELSE p.PartCode END,
             p.QRCode = ''
FROM Nexus.Parts p
JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @stk;
DECLARE @dash INT = @@ROWCOUNT;

-- 4) new PART B -> new hidden STORE-SUB items
DECLARE @new TABLE (PartID INT);
INSERT INTO Nexus.Parts (PartCode, PartB, Category, Model, PartNumber, Description, PackSize, QRCode, Bin, MaxQuantity, MinQuantity, IsActive, IsShowInMaster)
OUTPUT inserted.PartID INTO @new
SELECT '-', e.Code, N'B', e.Model, e.PartNo, e.Name, ISNULL(e.Pack, 0), '', '', 0, 0, 1, 0
FROM #e e
WHERE NOT EXISTS (SELECT 1 FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @stk WHERE LTRIM(RTRIM(p.PartB)) = e.Code);
DECLARE @ins INT = @@ROWCOUNT;
INSERT INTO Nexus.PartStocks (StockID, PartID, Quantity, MaxQuantity, MinQuantity, BoxQuantity, IsShow)
SELECT @stk, PartID, 0, 0, 0, 0, 0 FROM @new;

SELECT @upd AS UpdatedFromErp, @dash AS SubItemsCodeQrCleaned, @ins AS NewHiddenItems,
       (SELECT COUNT(*) FROM Nexus.PartStocks WHERE StockID = @stk) AS SubTotal,
       (SELECT COUNT(*) FROM Nexus.PartStocks WHERE StockID = @stk AND IsShow = 1) AS SubShown,
       (SELECT COUNT(*) FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @stk WHERE p.PartCode <> '-') AS SubCodeNotDash;

IF @apply = 1 COMMIT TRAN; ELSE ROLLBACK TRAN;
SELECT CASE WHEN @apply = 1 THEN N'APPLIED' ELSE N'DRY RUN - rolled back' END AS Result;
GO
SET NOEXEC OFF;
GO
